<?php
/**
 * Plugin Name: SENuke AI Connector
 * Description: Secure WordPress deployment bridge for complete SENuke AI website releases: pages/posts, media, SEO/schema, menus, forms, managed runtime theme, backups and rollback.
 * Version: 1.5.5
 * Author: SENuke AI
 */
if (!defined('ABSPATH')) exit;

final class SENuke_AI_Connector {
    const NS='senuke/v1';
    const FORM_OPTION='senuke_ai_forms';
    const STYLE_OPTION='senuke_ai_design_package';
    const STYLE_RELEASES_OPTION='senuke_ai_release_design_packages';
    const BACKUP_OPTION='senuke_ai_deployment_backups';
    const IDENTITY_OPTION='senuke_ai_site_identity';
    const IDENTITY_RELEASES_OPTION='senuke_ai_release_identities';
    const MENU_OPTION='senuke_ai_navigation_menus';
    const THEME_STYLESHEET='senuke-theme';
    const VERSION='1.5.5';

    public static function boot(){add_action('init',[__CLASS__,'register_blocks']);add_action('init',[__CLASS__,'register_seo_meta']);add_action('enqueue_block_editor_assets',[__CLASS__,'enqueue_editor_assets']);add_filter('block_categories_all',[__CLASS__,'block_categories'],10,2);add_action('rest_api_init',[__CLASS__,'routes']);add_action('add_meta_boxes',[__CLASS__,'add_seo_meta_boxes']);add_action('save_post',[__CLASS__,'save_seo_meta_box']);add_action('wp_head',[__CLASS__,'head_meta'],2);add_action('wp_enqueue_scripts',[__CLASS__,'enqueue_design_package'],30);add_action('template_redirect',[__CLASS__,'render_release_page'],1);add_filter('pre_get_document_title',[__CLASS__,'document_title'],99);add_filter('wp_robots',[__CLASS__,'robots_directives'],99);add_shortcode('senuke_form',[__CLASS__,'form_shortcode']);add_shortcode('senuke_identity',[__CLASS__,'identity_shortcode']);add_shortcode('senuke_footer_legal',[__CLASS__,'footer_legal_shortcode']);add_action('admin_post_senuke_form_submit',[__CLASS__,'form_submit']);add_action('admin_post_nopriv_senuke_form_submit',[__CLASS__,'form_submit']);}
    public static function block_categories($categories,$context){foreach($categories as $category)if(($category['slug']??'')==='senuke-sections')return $categories;array_unshift($categories,['slug'=>'senuke-sections','title'=>'SENuke Sections','icon'=>'layout']);return $categories;}
    public static function register_blocks(){
        wp_register_script('senuke-ai-blocks',plugins_url('senuke-blocks.js',__FILE__),['wp-blocks','wp-element','wp-block-editor','wp-components','wp-i18n','wp-rich-text','wp-data','wp-plugins','wp-edit-post','wp-editor'],self::VERSION,true);
        wp_register_style('senuke-ai-blocks-editor',plugins_url('senuke-blocks.css',__FILE__),[],self::VERSION);
        $blocks=['header','navigation','section-layout','local-service-hero','rich-text','image','service-grid','benefits','process','proof','faq','cta','contact-form','footer'];
        $attributes=['componentId'=>['type'=>'string'],'instanceId'=>['type'=>'string'],'componentVersion'=>['type'=>'string','default'=>'1.0.0'],'variant'=>['type'=>'string','default'=>'standard'],'props'=>['type'=>'object','default'=>[]],'lock'=>['type'=>'object'],'align'=>['type'=>'string'],'style'=>['type'=>'object'],'backgroundColor'=>['type'=>'string'],'textColor'=>['type'=>'string'],'gradient'=>['type'=>'string'],'fontSize'=>['type'=>'string']];
        $supports=['html'=>false,'reusable'=>true,'lock'=>true,'anchor'=>true,'align'=>['wide','full'],'color'=>['background'=>true,'text'=>true,'gradients'=>true],'spacing'=>['padding'=>true,'margin'=>true,'blockGap'=>true],'typography'=>['fontSize'=>true,'lineHeight'=>true],'border'=>['color'=>true,'radius'=>true,'style'=>true,'width'=>true]];
        foreach($blocks as $name)register_block_type('senuke/'.$name,['api_version'=>2,'editor_script'=>'senuke-ai-blocks','style'=>'senuke-ai-blocks-editor','editor_style'=>'senuke-ai-blocks-editor','render_callback'=>[__CLASS__,'render_component_block'],'attributes'=>$attributes,'supports'=>$supports]);
        self::register_block_patterns();
    }
    public static function enqueue_editor_assets(){wp_enqueue_script('senuke-ai-blocks');wp_enqueue_style('senuke-ai-blocks-editor');}
    public static function register_seo_meta(){
        $definitions=[
            '_senuke_meta_title'=>['type'=>'string','sanitize_callback'=>'sanitize_text_field'],
            '_senuke_meta_description'=>['type'=>'string','sanitize_callback'=>'sanitize_textarea_field'],
            '_senuke_canonical_url'=>['type'=>'string','sanitize_callback'=>'esc_url_raw'],
            '_senuke_robots'=>['type'=>'string','sanitize_callback'=>'sanitize_text_field'],
            '_senuke_schema_json'=>['type'=>'string','sanitize_callback'=>[__CLASS__,'sanitize_schema_meta']],
        ];
        foreach(['page','post'] as $post_type)foreach($definitions as $key=>$args)register_post_meta($post_type,$key,array_merge($args,['single'=>true,'show_in_rest'=>true,'auth_callback'=>fn()=>current_user_can('edit_posts')]));
    }
    public static function sanitize_schema_meta($value){$value=is_string($value)?wp_unslash($value):'';if(trim($value)==='')return'';$decoded=json_decode($value,true);return json_last_error()===JSON_ERROR_NONE?wp_json_encode($decoded):'';}
    public static function add_seo_meta_boxes(){foreach(['page','post'] as $post_type)add_meta_box('senuke-page-seo','SENuke Page SEO',[__CLASS__,'render_seo_meta_box'],$post_type,'normal','high');}
    public static function render_seo_meta_box($post){
        wp_nonce_field('senuke_save_page_seo','senuke_page_seo_nonce');
        $title=(string)get_post_meta($post->ID,'_senuke_meta_title',true);$description=(string)get_post_meta($post->ID,'_senuke_meta_description',true);$canonical=(string)get_post_meta($post->ID,'_senuke_canonical_url',true);$robots=(string)get_post_meta($post->ID,'_senuke_robots',true)?:'index, follow';$schema=(string)get_post_meta($post->ID,'_senuke_schema_json',true);
        $discouraged=(string)get_option('blog_public','1')==='0';
        echo'<div class="senuke-seo-fields">';if($discouraged)echo'<p style="border:1px solid #d63638;background:#fcf0f1;padding:10px 12px"><strong>Search visibility is disabled for this WordPress site.</strong> Published pages will output noindex until Settings → Reading → “Discourage search engines” is turned off.</p>';
        echo'<p><label><strong>SEO title</strong><br><input class="widefat" type="text" maxlength="70" name="senuke_meta_title" value="'.esc_attr($title).'"></label></p>';
        echo'<p><label><strong>Meta description</strong><br><textarea class="widefat" rows="3" maxlength="170" name="senuke_meta_description">'.esc_textarea($description).'</textarea></label></p>';
        echo'<p><label><strong>Canonical URL</strong><br><input class="widefat" type="url" name="senuke_canonical_url" value="'.esc_attr($canonical).'" placeholder="'.esc_attr(get_permalink($post)).'"></label></p>';
        echo'<p><label><strong>Search engine access</strong><br><select name="senuke_robots"><option value="index, follow"'.selected($robots,'index, follow',false).'>Index and follow</option><option value="noindex, follow"'.selected($robots,'noindex, follow',false).'>Do not index; follow links</option><option value="noindex, nofollow"'.selected($robots,'noindex, nofollow',false).'>Do not index or follow</option></select></label></p>';
        echo'<p><label><strong>Schema JSON-LD</strong><br><textarea class="widefat code" rows="8" name="senuke_schema_json">'.esc_textarea($schema).'</textarea></label><br><small>Use valid JSON. Invalid schema is not saved.</small></p></div>';
    }
    public static function save_seo_meta_box($post_id){
        if(!isset($_POST['senuke_page_seo_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['senuke_page_seo_nonce'])),'senuke_save_page_seo')||defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE||!current_user_can('edit_post',$post_id))return;
        $post_type=get_post_type($post_id);if(!in_array($post_type,['page','post'],true))return;
        $canonical=esc_url_raw(wp_unslash($_POST['senuke_canonical_url']??''));if($canonical&&strpos($canonical,'/')===0)$canonical=home_url($canonical);
        $fields=['_senuke_meta_title'=>sanitize_text_field(wp_unslash($_POST['senuke_meta_title']??'')),'_senuke_meta_description'=>sanitize_textarea_field(wp_unslash($_POST['senuke_meta_description']??'')),'_senuke_canonical_url'=>$canonical,'_senuke_robots'=>sanitize_text_field(wp_unslash($_POST['senuke_robots']??'index, follow')),'_senuke_schema_json'=>self::sanitize_schema_meta($_POST['senuke_schema_json']??'')];
        foreach($fields as $key=>$value){if($value==='')delete_post_meta($post_id,$key);else update_post_meta($post_id,$key,$value);}
    }
    private static function pattern_block($name,$component_id,$props,$variant='standard'){$attributes=['componentId'=>$component_id,'instanceId'=>'senuke-manual-'.wp_generate_uuid4(),'componentVersion'=>'1.0.0','variant'=>$variant,'props'=>$props];return'<!-- wp:senuke/'.$name.' '.wp_json_encode($attributes).' /-->';}
    private static function register_block_patterns(){
        if(!function_exists('register_block_pattern'))return;
        if(function_exists('register_block_pattern_category'))register_block_pattern_category('senuke-sections',['label'=>'SENuke Sections']);
        $patterns=[
            'hero'=>['Hero','local-service-hero','hero.local_service',['eyebrow'=>'Welcome','headline'=>'Add a clear customer-focused headline','summary'=>'Explain the value of this page and the next step.','primaryCtaLabel'=>'Get started','primaryCtaUrl'=>'#contact'],'split'],
            'introduction'=>['Introduction','rich-text','content.rich_text',['heading'=>'Introduce this topic','body'=>'Add useful, audience-focused information here.'],'standard'],
            'services'=>['Services Grid','service-grid','service.grid',['heading'=>'How we can help','introduction'=>'Choose the services most relevant to this page.','items'=>[['title'=>'Service one','description'=>'Explain the outcome this service provides.','url'=>'#'],['title'=>'Service two','description'=>'Explain the outcome this service provides.','url'=>'#'],['title'=>'Service three','description'=>'Explain the outcome this service provides.','url'=>'#']]],'cards'],
            'benefits'=>['Benefits','benefits','service.benefits',['heading'=>'Why choose us','items'=>[['title'=>'Clear benefit','description'=>'Add supporting detail.'],['title'=>'Trusted experience','description'=>'Add supporting detail.'],['title'=>'Helpful next step','description'=>'Add supporting detail.']]],'cards'],
            'process'=>['Process','process','content.process',['heading'=>'How it works','steps'=>[['title'=>'Start','description'=>'Describe the first step.'],['title'=>'Plan','description'=>'Describe the second step.'],['title'=>'Complete','description'=>'Describe the outcome.']]],'numbered'],
            'proof'=>['Trust & Proof','proof','trust.proof',['heading'=>'Why customers trust us','introduction'=>'Use verified facts and approved proof only.','items'=>[['title'=>'Evidence','description'=>'Add a verified trust signal.'],['title'=>'Experience','description'=>'Add a verified trust signal.']]],'cards'],
            'faq'=>['FAQ','faq','content.faq',['heading'=>'Frequently asked questions','items'=>[['question'=>'Add a customer question','answer'=>'Add a useful, factual answer.'],['question'=>'Add another question','answer'=>'Add a useful, factual answer.']]],'accordion'],
            'cta'=>['Call to Action','cta','conversion.cta',['heading'=>'Ready to take the next step?','body'=>'Explain what happens after the customer responds.','buttonLabel'=>'Contact us','buttonUrl'=>'#contact'],'band'],
            'contact'=>['Contact Form','contact-form','conversion.contact_form',['heading'=>'Contact us','introduction'=>'Tell customers how the team will respond.','submitLabel'=>'Send enquiry','successMessage'=>'Thank you. Your enquiry has been received.'],'standard'],
        ];
        foreach($patterns as $slug=>$pattern)register_block_pattern('senuke/'.$slug,['title'=>$pattern[0],'categories'=>['senuke-sections'],'blockTypes'=>['senuke/'.$pattern[1]],'inserter'=>true,'content'=>self::pattern_block($pattern[1],$pattern[2],$pattern[3],$pattern[4])]);
    }
    private static function block_value($props,$key,$fallback=''){return isset($props[$key])&&is_scalar($props[$key])?(string)$props[$key]:$fallback;}
    private static function block_rich($props,$key,$fallback=''){return wp_kses_post(self::block_value($props,$key,$fallback));}
    private static function block_items($props,$key){return isset($props[$key])&&is_array($props[$key])?$props[$key]:[];}
    private static function block_alignment($props){$alignment=sanitize_key(self::block_value($props,'alignment','left'));return in_array($alignment,['left','center','right'],true)?' senuke-align-'.$alignment:'';}
    private static function block_button($label,$url){$label=trim((string)$label);if($label==='')return'';return'<a class="senuke-button" href="'.esc_url($url?:'#').'">'.esc_html($label).'</a>';}
    private static function block_cards($items,$extra=''){if(!$items)return'';$html='<div class="senuke-grid">';foreach($items as $item){if(!is_array($item))continue;$title=self::block_value($item,'title',self::block_value($item,'name'));$body=self::block_value($item,'description',self::block_value($item,'body',self::block_value($item,'text')));$url=self::block_value($item,'url');$html.='<article class="senuke-card '.$extra.'">'.($title?'<h3>'.wp_kses_post($title).'</h3>':'').($body?wp_kses_post(wpautop($body)):'').($url?'<a href="'.esc_url($url).'">Learn more</a>':'').'</article>';}$html.='</div>';return$html;}
    private static function render_nested_component($component){if(!is_array($component))return'';return self::render_component_block(['componentId'=>sanitize_text_field($component['componentId']??''),'instanceId'=>sanitize_text_field($component['instanceId']??''),'componentVersion'=>sanitize_text_field($component['componentVersion']??'1.0.0'),'variant'=>sanitize_key($component['variant']??'standard'),'props'=>is_array($component['props']??null)?$component['props']:[]],'',null);}
    public static function render_component_block($attributes,$content='',$block=null){
        $id=sanitize_text_field($attributes['componentId']??'');
        $variant=sanitize_key($attributes['variant']??'standard');
        $props=is_array($attributes['props']??null)?$attributes['props']:[];
        $second=!empty($props['isSecondFold'])?' senuke-second-fold':'';
        $alignment=$second.self::block_alignment($props);
        $heading=self::block_value($props,'heading');
        $wrap=static function($html){$wrapper=get_block_wrapper_attributes(['class'=>'senuke-gutenberg-block']);return'<div '.$wrapper.'>'.$html.'</div>';};
        switch($id){
            case'layout.section':
                $layout=in_array($variant,['one_column','two_equal','two_left_wide','two_right_wide','three_equal'],true)?$variant:'two_equal';
                $columns=trim((string)$content);
                if($columns===''){$slots=$layout==='one_column'?['columnOne']:($layout==='three_equal'?['columnOne','columnTwo','columnThree']:['columnOne','columnTwo']);$columns='';foreach($slots as $index=>$slot){$children='';foreach(self::block_items($props,$slot)as$child)$children.=self::render_nested_component($child);$columns.='<div class="senuke-layout-column" data-column="'.($index+1).'">'.$children.'</div>';}}
                $background=sanitize_key(self::block_value($props,'backgroundColor','default'));$text=sanitize_key(self::block_value($props,'textColor','auto'));$spacing=sanitize_key(self::block_value($props,'spacing','comfortable'));$image=esc_url(self::block_value($props,'backgroundImageUrl'));$media=$image?'<img class="senuke-layout-background-image" src="'.$image.'" alt="" aria-hidden="true">':'';
                return$wrap('<section class="senuke-component senuke-layout-section'.$second.' senuke-layout-'.$layout.' senuke-layout-bg-'.$background.' senuke-layout-text-'.$text.' senuke-layout-spacing-'.$spacing.'">'.$media.'<div class="senuke-layout-columns">'.$columns.'</div></section>');
            case'hero.local_service':$image=esc_url(self::block_value($props,'imageUrl'));$media=$image?'<img class="senuke-hero-image" src="'.$image.'" alt="'.esc_attr(wp_strip_all_tags(self::block_value($props,'imageAltText',self::block_value($props,'headline')))).'">':'';return$wrap('<section class="senuke-component senuke-hero senuke-'.$variant.$alignment.'"><div>'.(self::block_value($props,'eyebrow')?'<p class="senuke-eyebrow">'.self::block_rich($props,'eyebrow').'</p>':'').'<h1>'.self::block_rich($props,'headline').'</h1><div class="senuke-lead">'.wp_kses_post(wpautop(self::block_value($props,'summary'))).'</div>'.self::block_button(self::block_value($props,'primaryCtaLabel'),self::block_value($props,'primaryCtaUrl')).'</div>'.$media.'</section>');
            case'content.rich_text':return$wrap('<section class="senuke-component senuke-rich-text'.$alignment.'"><h2>'.wp_kses_post($heading).'</h2>'.wp_kses_post(wpautop(self::block_value($props,'body'))).'</section>');
            case'media.image':$image=esc_url(self::block_value($props,'imageUrl'));return$wrap('<figure class="senuke-component senuke-media'.$second.' senuke-media-'.$variant.'">'.($image?'<img src="'.$image.'" alt="'.esc_attr(self::block_value($props,'imageAltText',self::block_value($props,'altText'))).'">':'').(self::block_value($props,'caption')?'<figcaption>'.esc_html(self::block_value($props,'caption')).'</figcaption>':'').'</figure>');
            case'service.grid':return$wrap('<section class="senuke-component senuke-services senuke-services-'.$variant.$alignment.'"><h2>'.wp_kses_post($heading).'</h2>'.(self::block_value($props,'introduction')?wp_kses_post(wpautop(self::block_value($props,'introduction'))):'').self::block_cards(self::block_items($props,'items')).'</section>');
            case'service.benefits':return$wrap('<section class="senuke-component senuke-benefits senuke-benefits-'.$variant.$alignment.'"><h2>'.wp_kses_post($heading).'</h2>'.self::block_cards(self::block_items($props,'items'),'senuke-benefit').'</section>');
            case'content.process':$steps='<ol class="senuke-steps">';foreach(self::block_items($props,'steps')as$item){if(!is_array($item))continue;$steps.='<li><h3>'.wp_kses_post(self::block_value($item,'title',self::block_value($item,'name'))).'</h3>'.wp_kses_post(wpautop(self::block_value($item,'description',self::block_value($item,'body')))).'</li>';}$steps.='</ol>';return$wrap('<section class="senuke-component senuke-process senuke-process-'.$variant.$alignment.'"><h2>'.wp_kses_post($heading).'</h2>'.$steps.'</section>');
            case'trust.proof':return$wrap('<section class="senuke-component senuke-proof'.$alignment.'"><h2>'.wp_kses_post($heading).'</h2>'.(self::block_value($props,'introduction')?wp_kses_post(wpautop(self::block_value($props,'introduction'))):'').self::block_cards(self::block_items($props,'items')).'</section>');
            case'content.faq':$faqs='';foreach(self::block_items($props,'items')as$item){if(!is_array($item))continue;$faqs.='<details><summary>'.wp_kses_post(self::block_value($item,'question',self::block_value($item,'title'))).'</summary>'.wp_kses_post(wpautop(self::block_value($item,'answer',self::block_value($item,'description')))).'</details>';}return$wrap('<section class="senuke-component senuke-faq'.$alignment.'"><h2>'.wp_kses_post($heading).'</h2>'.$faqs.'</section>');
            case'conversion.cta':return$wrap('<section class="senuke-component senuke-cta'.$alignment.'"><h2>'.wp_kses_post($heading).'</h2>'.wp_kses_post(wpautop(self::block_value($props,'body'))).self::block_button(self::block_value($props,'buttonLabel'),self::block_value($props,'buttonUrl')).'</section>');
            case'conversion.contact_form':$shortcode=self::block_value($props,'formShortcode');$form=$shortcode?do_shortcode($shortcode):'<p class="senuke-form-placeholder">Connect the approved SENuke form before publishing.</p>';return$wrap('<section class="senuke-component senuke-contact-form senuke-contact-form-shortcode'.$alignment.'"><div><h2>'.wp_kses_post($heading).'</h2>'.wp_kses_post(wpautop(self::block_value($props,'introduction'))).'</div><div>'.$form.'</div></section>');
            case'global.navigation':
                $location=sanitize_key(self::block_value($props,'location','primary'));if(!in_array($location,['primary','footer'],true))$location='primary';$name=$location==='footer'?'SENuke Footer Navigation':'SENuke Primary Navigation';$class=$location==='footer'?'senuke-footer-navigation':'senuke-primary-nav';$menu=self::release_menu($name,$class,$location);if(!$menu)return'';if($location==='footer')return$menu;$mobile=self::release_menu($name,$class.' senuke-primary-nav-mobile',$location);return'<div class="senuke-managed-navigation"><div class="senuke-header-navigation">'.$menu.'</div><details class="senuke-mobile-menu"><summary aria-label="Open navigation menu"><span class="senuke-menu-icon" aria-hidden="true"><i></i><i></i><i></i></span><span class="senuke-visually-hidden">Menu</span></summary><div class="senuke-mobile-menu-panel">'.$mobile.'</div></details></div>';
            case'global.header':return$wrap('<header class="senuke-component senuke-header"><strong>'.esc_html(self::block_value($props,'businessName')).'</strong>'.self::block_button(self::block_value($props,'primaryCtaLabel'),self::block_value($props,'primaryCtaUrl')).'</header>');
            case'global.footer':return$wrap('<footer class="senuke-component senuke-footer"><strong>'.esc_html(self::block_value($props,'businessName')).'</strong>'.(self::block_value($props,'summary')?'<p>'.esc_html(self::block_value($props,'summary')).'</p>':'').'</footer>');
        }
        return$content;
    }
    public static function routes(){
        register_rest_route(self::NS,'/capabilities',['methods'=>'GET','permission_callback'=>fn()=>current_user_can('edit_pages'),'callback'=>[__CLASS__,'capabilities']]);
        register_rest_route(self::NS,'/pages/(?P<id>\d+)/optimize',['methods'=>'POST','permission_callback'=>fn($r)=>current_user_can('edit_post',(int)$r['id']),'callback'=>[__CLASS__,'optimize_page']]);
        register_rest_route(self::NS,'/menus',['methods'=>'POST','permission_callback'=>fn()=>current_user_can('edit_theme_options'),'callback'=>[__CLASS__,'create_menu']]);
        register_rest_route(self::NS,'/forms',['methods'=>'POST','permission_callback'=>fn()=>current_user_can('edit_pages'),'callback'=>[__CLASS__,'save_form']]);
        register_rest_route(self::NS,'/backups',['methods'=>'POST','permission_callback'=>fn()=>current_user_can('manage_options'),'callback'=>[__CLASS__,'create_backup']]);
        register_rest_route(self::NS,'/backups/(?P<id>[a-zA-Z0-9_-]+)/restore',['methods'=>'POST','permission_callback'=>fn()=>current_user_can('manage_options'),'callback'=>[__CLASS__,'restore_backup']]);
        register_rest_route(self::NS,'/site-package',['methods'=>'POST','permission_callback'=>fn()=>current_user_can('edit_theme_options'),'callback'=>[__CLASS__,'save_design_package']]);
        register_rest_route(self::NS,'/site-identity',['methods'=>'POST','permission_callback'=>fn()=>current_user_can('edit_theme_options'),'callback'=>[__CLASS__,'save_site_identity']]);
        register_rest_route(self::NS,'/theme-status',['methods'=>'GET','permission_callback'=>fn()=>current_user_can('edit_theme_options'),'callback'=>fn()=>rest_ensure_response(self::theme_state())]);
        register_rest_route(self::NS,'/theme-install',['methods'=>'POST','permission_callback'=>fn()=>current_user_can('manage_options')&&current_user_can('switch_themes'),'callback'=>[__CLASS__,'install_theme']]);
        register_rest_route(self::NS,'/theme-activate',['methods'=>'POST','permission_callback'=>fn()=>current_user_can('switch_themes'),'callback'=>[__CLASS__,'activate_theme']]);
    }
    public static function capabilities(){return rest_ensure_response(['connected'=>true,'version'=>self::VERSION,'features'=>['seo_meta','robots_meta','schema','favicon','gutenberg_blocks','full_site_editing','editable_theme','senuke_theme','menus','forms','site_backup','design_package','release_scoped_layout','rollback','theme_runtime','theme_install','site_identity'],'managedDeploymentReady'=>current_user_can('publish_pages')&&current_user_can('upload_files')&&current_user_can('edit_theme_options')&&current_user_can('manage_options')&&current_user_can('switch_themes'),'permissions'=>['publishPages'=>current_user_can('publish_pages'),'uploadMedia'=>current_user_can('upload_files'),'manageNavigationAndDesign'=>current_user_can('edit_theme_options'),'backupAndRollback'=>current_user_can('manage_options'),'switchTheme'=>current_user_can('switch_themes')],'theme'=>self::theme_state()]);}

