        if($field==='copyright')return esc_html($identity['copyrightText']??('© '.gmdate('Y').' '.($identity['businessName']??get_bloginfo('name')).'. All rights reserved.'));
        if(in_array($field,['social','header_social'],true)){$links=self::release_social_links($identity);return $field==='header_social'?str_replace('class="senuke-social-links"','class="senuke-social-links senuke-header-social"',$links):$links;}
        if($field==='contact'){
            $items=[];
            if(!empty($identity['businessAddress']))$items[]='<span>'.esc_html($identity['businessAddress']).'</span>';
            if(!empty($identity['contactPhone']))$items[]='<a href="tel:'.esc_attr(preg_replace('/[^\d+]/','',(string)$identity['contactPhone'])).'">'.esc_html($identity['contactPhone']).'</a>';
            if(!empty($identity['contactEmail']))$items[]='<a href="mailto:'.esc_attr($identity['contactEmail']).'">'.esc_html($identity['contactEmail']).'</a>';
