    private static function release_menu($name,$class,$location=''){
        static $instance=0;$release=self::current_release_id();$menu=$release?wp_get_nav_menu_object($name.' '.$release):null;if(!$menu)$menu=wp_get_nav_menu_object($name);if(!$menu){$managed=get_option(self::MENU_OPTION,[]);$managed_id=is_array($managed)?absint($managed[sanitize_key($location)]??0):0;if($managed_id)$menu=wp_get_nav_menu_object($managed_id);}if(!$menu)return'';
        $instance++;$html=wp_nav_menu(['menu'=>(int)$menu->term_id,'container'=>'nav','container_class'=>$class,'menu_class'=>'senuke-menu','menu_id'=>sanitize_html_class($class.'-items-'.$instance),'fallback_cb'=>false,'depth'=>8,'echo'=>false]);if(!is_string($html))return'';
        if($location==='footer')$html=preg_replace_callback('~<a\s+([^>]*\s)?href=(["\'])#\2([^>]*)>(.*?)</a>~is',static fn($match)=>'<span class="senuke-menu-heading">'.$match[4].'</span>',$html)??$html;
        return$html;
    }
