    public static function render_release_page(){
        if(!self::is_release_page())return;
        if(function_exists('wp_is_block_theme')&&wp_is_block_theme()&&wp_get_theme()->get_stylesheet()===self::THEME_STYLESHEET)return;
        $identity=self::current_identity();
        $brand=self::release_brand($identity);
        $primary=self::release_menu('SENuke Primary Navigation','senuke-primary-nav','primary');
        $footer=self::release_menu('SENuke Footer Navigation','senuke-footer-navigation','footer');
        $social=self::release_social_links($identity);
        $header_social=str_replace('class="senuke-social-links"','class="senuke-social-links senuke-header-social"',$social);
        $summary=trim((string)($identity['businessSummary']??''));
        $contact=[];
        if(!empty($identity['businessAddress']))$contact[]='<span>'.esc_html($identity['businessAddress']).'</span>';
        if(!empty($identity['contactPhone']))$contact[]='<a href="tel:'.esc_attr(preg_replace('/[^\d+]/','',(string)$identity['contactPhone'])).'">'.esc_html($identity['contactPhone']).'</a>';
        if(!empty($identity['contactEmail']))$contact[]='<a href="mailto:'.esc_attr($identity['contactEmail']).'">'.esc_html($identity['contactEmail']).'</a>';
        status_header(200);?><!doctype html><html <?php language_attributes();?>><head><meta charset="<?php bloginfo('charset');?>"><meta name="viewport" content="width=device-width,initial-scale=1"><?php wp_head();?></head><body <?php body_class('senuke-release-page');?>><?php wp_body_open();?><div class="senuke-site-topbar"><div class="senuke-site-topbar-inner"><?php echo $header_social;?><?php if($contact):?><div class="senuke-header-contact"><?php echo implode('',$contact);?></div><?php endif;?></div></div><header class="senuke-site-header"><a class="senuke-brand" href="<?php echo esc_url(home_url('/'));?>"><?php echo $brand;?></a><div class="senuke-header-navigation"><?php echo $primary;?></div><details class="senuke-mobile-menu"><summary aria-label="Open navigation menu"><span class="senuke-menu-icon" aria-hidden="true"><i></i><i></i><i></i></span><span class="senuke-visually-hidden">Menu</span></summary><div class="senuke-mobile-menu-panel"><?php echo $primary;?></div></details></header><main><?php while(have_posts()):the_post();the_content();endwhile;?></main><footer class="senuke-site-footer"><div class="senuke-footer-main"><section class="senuke-footer-brand"><a class="senuke-footer-logo" href="<?php echo esc_url(home_url('/'));?>"><?php echo $brand;?></a><?php if($summary):?><p><?php echo esc_html($summary);?></p><?php endif;echo $social;?></section><div class="senuke-footer-navigation-column"><?php echo $footer;?></div><section class="senuke-footer-contact-column"><h2>Get in touch</h2><?php if($contact):?><div class="senuke-footer-contact"><?php echo implode('',$contact);?></div><?php endif;?></section></div><div class="senuke-footer-bottom"><p class="senuke-footer-copyright"><?php echo esc_html($identity['copyrightText']??('© '.gmdate('Y').' '.get_bloginfo('name').'. All rights reserved.'));?></p><?php echo self::footer_legal_shortcode();?></div></footer><?php wp_footer();?></body></html><?php exit;
    }

    public static function create_menu(WP_REST_Request $r){
        $d=$r->get_json_params();$name=sanitize_text_field($d['name']??'SENuke Primary Navigation');$menu=wp_get_nav_menu_object($name);$id=$menu?(int)$menu->term_id:wp_create_nav_menu($name);if(is_wp_error($id))return$id;
        foreach(wp_get_nav_menu_items($id)?:[]as$old)wp_delete_post($old->ID,true);
        $created=[];$pending=array_values((array)($d['items']??[]));$pos=1;
        for($pass=0;$pass<100&&$pending;$pass++){$remaining=[];foreach($pending as$item){if(!is_array($item))continue;$source=sanitize_key($item['id']??'');$parent=sanitize_key($item['parentId']??'');if($parent&&empty($created[$parent])){$remaining[]=$item;continue;}$new=wp_update_nav_menu_item($id,0,['menu-item-title'=>sanitize_text_field($item['label']??'Page'),'menu-item-url'=>esc_url_raw($item['url']??home_url('/')),'menu-item-parent-id'=>$parent?(int)$created[$parent]:0,'menu-item-status'=>'publish','menu-item-position'=>$pos++]);if(!is_wp_error($new)&&$source)$created[$source]=(int)$new;}if(count($remaining)===count($pending))break;$pending=$remaining;}
        $locations=get_theme_mod('nav_menu_locations',[]);$registered=get_registered_nav_menus();$requested=sanitize_key($d['location']??'');if(!in_array($requested,['primary','footer'],true))$requested='primary';$assign=!empty($d['assignLocation']);$preferred=isset($registered[$requested])?$requested:null;if(!$preferred&&$requested==='footer')foreach(array_keys($registered)as$loc)if(preg_match('/footer|bottom|secondary/i',$loc)){$preferred=$loc;break;}if(!$preferred&&$requested!=='footer')$preferred=isset($registered['primary'])?'primary':array_key_first($registered);
        if($assign){if($preferred){$locations[$preferred]=$id;set_theme_mod('nav_menu_locations',$locations);}$managed=get_option(self::MENU_OPTION,[]);if(!is_array($managed))$managed=[];$managed[$requested]=(int)$id;update_option(self::MENU_OPTION,$managed,false);}
        return rest_ensure_response(['menuId'=>$id,'location'=>$preferred,'managedLocation'=>$requested,'itemCount'=>count($created)]);
    }

    public static function save_form(WP_REST_Request $r){$d=$r->get_json_params();$key=sanitize_key($d['key']??'primary_contact');$forms=get_option(self::FORM_OPTION,[]);if(!is_array($forms))$forms=[];$fields=[];foreach((array)($d['fields']??[]) as $f){if(is_array($f)){$label=sanitize_text_field($f['label']??$f['name']??'Field');$name=sanitize_key($f['name']??$label);$type=sanitize_key($f['inputType']??$f['type']??'text');if(!in_array($type,['text','email','tel','textarea','checkbox'],true))$type='text';$fields[]=['label'=>$label,'name'=>$name,'inputType'=>$type,'required'=>!empty($f['required'])];}else{$label=sanitize_text_field($f);$fields[]=['label'=>$label,'name'=>sanitize_key($label),'inputType'=>preg_match('/message|details/i',$label)?'textarea':(stripos($label,'email')!==false?'email':'text'),'required'=>true];}}$forms[$key]=['name'=>sanitize_text_field($d['name']??'Contact form'),'fields'=>$fields,'submitLabel'=>sanitize_text_field($d['submitLabel']??'Submit'),'successMessage'=>sanitize_text_field($d['successMessage']??'Thank you. Your enquiry has been received.'),'destination'=>sanitize_email($d['destination']??get_option('admin_email'))];update_option(self::FORM_OPTION,$forms,false);return rest_ensure_response(['key'=>$key,'shortcode'=>'[senuke_form id="'.esc_attr($key).'"]']);}
    public static function form_shortcode($atts){$id=sanitize_key(shortcode_atts(['id'=>'primary_contact'],$atts)['id']);$forms=get_option(self::FORM_OPTION,[]);$form=is_array($forms)?($forms[$id]??null):null;if(!$form)return'';ob_start();?><form class="senuke-ai-form" method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="senuke_form_submit"><input type="hidden" name="senuke_form_id" value="<?php echo esc_attr($id);?>"><?php wp_nonce_field('senuke_form_'.$id,'senuke_nonce');foreach($form['fields'] as $f):$name=sanitize_key($f['name']??$f['label']);$type=$f['inputType']??'text';$req=!empty($f['required']);?><p><label><?php echo esc_html($f['label']);?><br><?php if($type==='textarea'):?><textarea name="<?php echo esc_attr($name);?>" <?php echo $req?'required':'';?>></textarea><?php elseif($type==='checkbox'):?><input name="<?php echo esc_attr($name);?>" type="checkbox" value="yes" <?php echo $req?'required':'';?>><?php else:?><input name="<?php echo esc_attr($name);?>" type="<?php echo esc_attr(in_array($type,['email','tel'],true)?$type:'text');?>" <?php echo $req?'required':'';?>><?php endif;?></label></p><?php endforeach;?><button type="submit"><?php echo esc_html($form['submitLabel']);?></button></form><?php return ob_get_clean();}
    public static function form_submit(){$id=sanitize_key($_POST['senuke_form_id']??'');if(!$id||!wp_verify_nonce($_POST['senuke_nonce']??'','senuke_form_'.$id))wp_die('Invalid form request.',403);$forms=get_option(self::FORM_OPTION,[]);$form=is_array($forms)?($forms[$id]??null):null;if(!$form)wp_die('Form unavailable.',404);$lines=[];foreach($form['fields'] as $f){$name=sanitize_key($f['name']??$f['label']);$lines[]=$f['label'].': '.sanitize_textarea_field(wp_unslash($_POST[$name]??''));}wp_mail($form['destination'],'Website enquiry: '.$form['name'],implode("\n",$lines));wp_safe_redirect(add_query_arg('senuke_enquiry','received',wp_get_referer()?:home_url('/')));exit;}

    public static function create_backup(WP_REST_Request $r){$d=$r->get_json_params();$id=sanitize_key('senuke-'.gmdate('Ymd-His').'-'.wp_generate_password(6,false,false));$theme=wp_get_theme();$snapshot=['backupId'=>$id,'createdAt'=>gmdate('c'),'releaseId'=>sanitize_text_field($d['releaseId']??''),'snapshotHash'=>sanitize_text_field($d['snapshotHash']??''),'site'=>['blogname'=>get_option('blogname'),'blogdescription'=>get_option('blogdescription'),'show_on_front'=>get_option('show_on_front'),'page_on_front'=>(int)get_option('page_on_front'),'page_for_posts'=>(int)get_option('page_for_posts'),'permalink_structure'=>get_option('permalink_structure')],'theme'=>['stylesheet'=>$theme->get_stylesheet()],'navigationLocations'=>get_theme_mod('nav_menu_locations',[]),'managedNavigationMenus'=>get_option(self::MENU_OPTION,[]),'designPackage'=>get_option(self::STYLE_OPTION,[]),'releaseDesignPackages'=>get_option(self::STYLE_RELEASES_OPTION,[]),'forms'=>get_option(self::FORM_OPTION,[]),'identity'=>get_option(self::IDENTITY_OPTION,[]),'releaseIdentities'=>get_option(self::IDENTITY_RELEASES_OPTION,[])];$backups=get_option(self::BACKUP_OPTION,[]);if(!is_array($backups))$backups=[];$backups[$id]=$snapshot;if(count($backups)>20)$backups=array_slice($backups,-20,null,true);update_option(self::BACKUP_OPTION,$backups,false);return rest_ensure_response(['backupId'=>$id,'createdAt'=>$snapshot['createdAt']]);}
    public static function restore_backup(WP_REST_Request $r){$id=sanitize_key($r['id']);$backups=get_option(self::BACKUP_OPTION,[]);$s=is_array($backups)?($backups[$id]??null):null;if(!$s)return new WP_Error('senuke_backup_not_found','The requested SENuke deployment backup was not found.',['status'=>404]);foreach((array)($s['site']??[]) as $k=>$v)update_option(sanitize_key($k),$v);$previous=sanitize_key($s['theme']['stylesheet']??'');if($previous&&wp_get_theme($previous)->exists()&&current_user_can('switch_themes'))switch_theme($previous);set_theme_mod('nav_menu_locations',(array)($s['navigationLocations']??[]));update_option(self::MENU_OPTION,(array)($s['managedNavigationMenus']??[]),false);update_option(self::STYLE_OPTION,(array)($s['designPackage']??[]),false);update_option(self::STYLE_RELEASES_OPTION,(array)($s['releaseDesignPackages']??[]),false);update_option(self::FORM_OPTION,(array)($s['forms']??[]),false);update_option(self::IDENTITY_OPTION,(array)($s['identity']??[]),false);update_option(self::IDENTITY_RELEASES_OPTION,(array)($s['releaseIdentities']??[]),false);flush_rewrite_rules(false);return rest_ensure_response(['restored'=>true,'backupId'=>$id,'restoredAt'=>gmdate('c')]);}

    public static function save_design_package(WP_REST_Request $r){
        $d=$r->get_json_params();
        $css=(string)($d['css']??'');
        if(strlen($css)>350000)return new WP_Error('senuke_css_too_large','The approved design package exceeds 350 KB.',['status'=>413]);
        if(preg_match('/(?:<\/?style\b|<script\b|@import\b|url\s*\(\s*["\']?\s*javascript\s*:|expression\s*\(|(?:^|[;{])\s*behavior\s*:|-moz-binding\s*:)/i',$css))return new WP_Error('senuke_css_rejected','The design package contains an unsupported CSS construct.',['status'=>400]);
        $scope=sanitize_key($d['scope']??'release_pages');
        if(!in_array($scope,['release_pages','global'],true))$scope='release_pages';
        $p=['releaseId'=>sanitize_text_field($d['releaseId']??''),'snapshotHash'=>sanitize_text_field($d['snapshotHash']??''),'scope'=>$scope,'css'=>$css,'savedAt'=>gmdate('c')];
        if(!$p['releaseId'])return new WP_Error('senuke_release_required','A release ID is required for the design package.',['status'=>400]);
        $packages=get_option(self::STYLE_RELEASES_OPTION,[]);
        if(!is_array($packages))$packages=[];
        $packages[$p['releaseId']]=$p;
        if(count($packages)>20)$packages=array_slice($packages,-20,null,true);
        update_option(self::STYLE_RELEASES_OPTION,$packages,false);

        $theme=self::theme_state();
        $activate_theme=!empty($d['activateTheme']);
        $refresh_active_senuke_theme=!$activate_theme&&$theme['active'];
        if($activate_theme||$refresh_active_senuke_theme){
            if($activate_theme)update_option(self::STYLE_OPTION,$p,false);
            if(!current_user_can('manage_options')||!current_user_can('switch_themes'))return new WP_Error('senuke_theme_permission_required','Refreshing SENuke Theme requires a WordPress administrator who can install and switch themes.',['status'=>403]);
            try{
                // Draft synchronization must refresh the bundled files when
                // SENuke Theme is already active. It does not switch themes or
                // publish pages; it only updates the editable theme package.
                $installed=self::ensure_theme();
                if(is_wp_error($installed))return $installed;
                if($activate_theme&&wp_get_theme()->get_stylesheet()!==self::THEME_STYLESHEET){
                    switch_theme(self::THEME_STYLESHEET);
                    self::refresh_theme_cache();
                }
                $theme=self::theme_state();
                if($activate_theme&&!$theme['active'])return new WP_Error('senuke_theme_not_activated','WordPress wrote the SENuke Theme files but did not activate the theme. Check wp-content/themes permissions and whether theme changes are disabled by the host.',['status'=>409]);
            }catch(Throwable $e){
                $detail=sanitize_text_field($e->getMessage());
                return new WP_Error('senuke_theme_activation_failed','WordPress could not install or refresh SENuke Theme'.($detail?': '.$detail:'.').' Keep the current theme active and check the server theme/file permissions before retrying.',['status'=>500]);
            }
        }
        return rest_ensure_response(['installed'=>$theme['installed'],'activated'=>$theme['active'],'scope'=>$scope,'releaseId'=>$p['releaseId'],'snapshotHash'=>$p['snapshotHash'],'bytes'=>strlen($css),'theme'=>$theme]);
    }
    public static function theme_state(){$t=wp_get_theme(self::THEME_STYLESHEET);$a=wp_get_theme();return['stylesheet'=>self::THEME_STYLESHEET,'installed'=>$t->exists(),'active'=>$a->get_stylesheet()===self::THEME_STYLESHEET,'version'=>$t->exists()?(string)$t->get('Version'):'','fullSiteEditing'=>$a->get_stylesheet()===self::THEME_STYLESHEET&&function_exists('wp_is_block_theme')&&wp_is_block_theme(),'activeStylesheet'=>$a->get_stylesheet(),'activeTheme'=>$a->get('Name')];}
    public static function install_theme(WP_REST_Request $r){$d=$r->get_json_params();$encoded=preg_replace('/\s+/','',(string)($d['packageBase64']??''));if(!$encoded){$result=self::ensure_theme();if(is_wp_error($result))return$result;if(!empty($d['activate']))switch_theme(self::THEME_STYLESHEET);self::refresh_theme_cache();return rest_ensure_response(['installed'=>true,'activated'=>wp_get_theme()->get_stylesheet()===self::THEME_STYLESHEET,'theme'=>self::theme_state()]);}$bytes=base64_decode($encoded,true);if($bytes===false||strlen($bytes)<100)return new WP_Error('senuke_theme_package_invalid','The SENuke Theme package is invalid.',['status'=>400]);require_once ABSPATH.'wp-admin/includes/file.php';if(!WP_Filesystem())return new WP_Error('senuke_filesystem_unavailable','WordPress could not initialize filesystem access.',['status'=>409]);$tmp=wp_tempnam('senuke-theme.zip');if(!$tmp||file_put_contents($tmp,$bytes)===false)return new WP_Error('senuke_theme_temp_failed','WordPress could not create a temporary theme package.',['status'=>500]);$result=unzip_file($tmp,get_theme_root());@unlink($tmp);if(is_wp_error($result))return$result;self::refresh_theme_cache();if(!empty($d['activate']))switch_theme(self::THEME_STYLESHEET);return rest_ensure_response(['installed'=>true,'activated'=>wp_get_theme()->get_stylesheet()===self::THEME_STYLESHEET,'theme'=>self::theme_state()]);}
    public static function activate_theme(){if(!wp_get_theme(self::THEME_STYLESHEET)->exists())return new WP_Error('senuke_theme_not_installed','Install SENuke Theme first.',['status'=>409]);switch_theme(self::THEME_STYLESHEET);return rest_ensure_response(['activated'=>true,'theme'=>self::theme_state()]);}
    private static function ensure_theme(){
        if(function_exists('wp_is_file_mod_allowed')&&!wp_is_file_mod_allowed('senuke_ai_theme'))return new WP_Error('senuke_theme_file_mods_disabled','This WordPress installation has theme file changes disabled. Ask the host or administrator to allow theme installation, then retry.',['status'=>409]);
        require_once ABSPATH.'wp-admin/includes/file.php';
        $filesystem_ready=WP_Filesystem();
        global $wp_filesystem;
        $root=trailingslashit(get_theme_root()).self::THEME_STYLESHEET;
        $files=self::theme_files();
        if($filesystem_ready&&$wp_filesystem){
            $dir_mode=defined('FS_CHMOD_DIR')?FS_CHMOD_DIR:0755;
            $file_mode=defined('FS_CHMOD_FILE')?FS_CHMOD_FILE:0644;
            if(!$wp_filesystem->is_dir($root)&&!$wp_filesystem->mkdir($root,$dir_mode))return new WP_Error('senuke_theme_directory_failed','WordPress could not create wp-content/themes/senuke-theme. Check the themes directory permissions.',['status'=>409]);
            foreach($files as $path=>$content){$target=$root.'/'.$path;$dir=dirname($target);if(!$wp_filesystem->is_dir($dir)&&!$wp_filesystem->mkdir($dir,$dir_mode))return new WP_Error('senuke_theme_subdirectory_failed','WordPress could not create the SENuke theme template directories. Check wp-content/themes permissions.',['status'=>409]);if(!$wp_filesystem->put_contents($target,$content,$file_mode))return new WP_Error('senuke_theme_write_failed','WordPress could not write '.$path.' in wp-content/themes/senuke-theme. Check file ownership and permissions.',['status'=>409]);}
        }else{
            if(!is_dir($root)&&!wp_mkdir_p($root))return new WP_Error('senuke_theme_directory_failed','WordPress filesystem access needs credentials and direct creation of wp-content/themes/senuke-theme also failed. Configure direct filesystem access or install the theme manually.',['status'=>409]);
            foreach($files as $path=>$content){$target=$root.'/'.$path;$dir=dirname($target);if(!is_dir($dir)&&!wp_mkdir_p($dir))return new WP_Error('senuke_theme_subdirectory_failed','WordPress could not create the SENuke theme template directories.',['status'=>409]);if(file_put_contents($target,$content,LOCK_EX)===false)return new WP_Error('senuke_theme_write_failed','WordPress could not write '.$path.' using direct filesystem access. Check wp-content/themes ownership and permissions.',['status'=>409]);}
        }
        self::refresh_theme_cache();
        $theme=wp_get_theme(self::THEME_STYLESHEET);
        if(!$theme->exists())return new WP_Error('senuke_theme_invalid','The SENuke theme files were written, but WordPress does not recognize the theme. Check the generated style.css and theme directory.',['status'=>409]);
        $errors=$theme->errors();
        if(is_wp_error($errors))return new WP_Error('senuke_theme_invalid','WordPress rejected SENuke Theme: '.$errors->get_error_message(),['status'=>409]);
        return['installed'=>true,'theme'=>self::theme_state()];
    }
    private static function refresh_theme_cache(){if(function_exists('wp_clean_themes_cache'))wp_clean_themes_cache(true);}
