    public static function save_site_identity(WP_REST_Request $r){$d=$r->get_json_params();$identity=['releaseId'=>sanitize_text_field($d['releaseId']??''),'snapshotHash'=>sanitize_text_field($d['snapshotHash']??''),'businessName'=>sanitize_text_field($d['businessName']??get_option('blogname')),'businessSummary'=>sanitize_textarea_field($d['businessSummary']??''),'logoUrl'=>esc_url_raw($d['logoUrl']??''),'logoMediaId'=>absint($d['logoMediaId']??0),'faviconUrl'=>esc_url_raw($d['faviconUrl']??''),'faviconMediaId'=>absint($d['faviconMediaId']??0),'contactEmail'=>sanitize_email($d['contactEmail']??''),'contactPhone'=>sanitize_text_field($d['contactPhone']??''),'businessAddress'=>sanitize_text_field($d['businessAddress']??''),'copyrightText'=>sanitize_text_field($d['copyrightText']??''),'socialProfiles'=>(array)($d['socialProfiles']??[])];if(!$identity['releaseId'])return new WP_Error('senuke_release_required','A release ID is required for the site identity.',['status'=>400]);$identities=get_option(self::IDENTITY_RELEASES_OPTION,[]);if(!is_array($identities))$identities=[];$identities[$identity['releaseId']]=$identity;if(count($identities)>20)$identities=array_slice($identities,-20,null,true);update_option(self::IDENTITY_RELEASES_OPTION,$identities,false);if(!empty($d['applySiteSettings'])){update_option(self::IDENTITY_OPTION,$identity,false);if($identity['businessName'])update_option('blogname',$identity['businessName']);if($identity['logoMediaId'])set_theme_mod('custom_logo',$identity['logoMediaId']);if($identity['faviconMediaId'])update_option('site_icon',$identity['faviconMediaId']);}return rest_ensure_response(['saved'=>true,'releaseId'=>$identity['releaseId'],'siteLogoApplied'=>(bool)$identity['logoMediaId'],'siteIconApplied'=>(bool)$identity['faviconMediaId']]);}
    private static function identity_from_schema($schema,$request=[]){if(is_string($schema))$schema=json_decode($schema,true);if(!is_array($schema))return;$release=sanitize_text_field($request['approvedReleaseId']??'');if(!$release)return;$identities=get_option(self::IDENTITY_RELEASES_OPTION,[]);if(!is_array($identities))$identities=[];$current=is_array($identities[$release]??null)?$identities[$release]:['releaseId'=>$release,'snapshotHash'=>sanitize_text_field($request['snapshotHash']??'')];$items=isset($schema['@graph'])&&is_array($schema['@graph'])?$schema['@graph']:[$schema];foreach($items as $item){if(!is_array($item))continue;$types=(array)($item['@type']??[]);if(!array_intersect($types,['Organization','LocalBusiness','ProfessionalService','Corporation']))continue;if(empty($current['businessName']))$current['businessName']=sanitize_text_field($item['name']??'');if(empty($current['contactEmail']))$current['contactEmail']=sanitize_email($item['email']??'');if(empty($current['contactPhone']))$current['contactPhone']=sanitize_text_field($item['telephone']??'');$identities[$release]=$current;update_option(self::IDENTITY_RELEASES_OPTION,$identities,false);break;}}
